head.script:
/* =====================================================================
 * QUẢN LÝ HỘI TRƯỜNG - SSC Check-in
 * API: /api/halls (xem API_EVENT_HALL.md)
 * ===================================================================== */

/* ---------- Cấu hình ---------- */
scwin.API_BASE = "http://localhost:8081";
scwin.HALL_API = scwin.API_BASE + "/api/halls";
// Key lưu trữ dùng chung với trang đăng nhập và Header (checkinCommon/Header.xml)
scwin.KEY = {
    TOKEN: "ssc_token",
    USER:  "ssc_user",
    PERMS: "ssc_permissions",
    MENUS: "ssc_menus"
};
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
// Tiền tố ứng dụng: "" khi chạy local, "/text" khi deploy (giống Header)
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.MAX_IMAGE_SIZE = 5 * 1024 * 1024;
scwin.IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/gif"];
scwin.EVENT_PAGE_SIZE = 5;

/* ---------- Trạng thái màn hình ---------- */
scwin.SEARCH_DEFAULT = { keyword: "", minCapacity: "", maxCapacity: "", active: "", sort: "hallId,desc", size: "10", page: "0" };
scwin.state = { totalPages: 0, totalElements: 0 };   // kết quả phân trang lần tìm gần nhất
scwin.searchSeq = 0;
scwin.searchTimer = null;
scwin.dupTimer = null;
scwin.toastTimer = null;
scwin.pagingLock = false;

scwin.current = null;          // hội trường đang mở trong panel chi tiết
scwin.drawerOpen = false;
scwin.formOpen = false;
scwin.deleteOpen = false;
scwin.deleteBusy = false;
scwin.ev = { page: 0, items: [], totalPages: 0, totalElements: 0, loading: false };

scwin.form = {
    mode: "create", hallId: null, originalName: "", active: true,
    file: null, previewUrl: null, removeImage: false, originalImage: null,
    dirty: false, saving: false
};

scwin.FIELDS = {
    hallName:    { input: "ibx_fName",     error: "tbx_fNameErr",     max: 150,  label: "Tên hội trường" },
    hallCode:    { input: "ibx_fCode",     error: "tbx_fCodeErr",     max: 30,   label: "Mã hội trường" },
    capacity:    { input: "ibx_fCapacity", error: "tbx_fCapacityErr",            label: "Sức chứa" },
    address:     { input: "ibx_fAddress",  error: "tbx_fAddressErr",  max: 500,  label: "Địa chỉ" },
    floorArea:   { input: "ibx_fFloor",    error: "tbx_fFloorErr",    max: 100,  label: "Tầng/Khu vực" },
    description: { input: "txa_fDesc",     error: "tbx_fDescErr",     max: 4000, label: "Mô tả/Tiện nghi" },
    notes:       { input: "txa_fNotes",    error: "tbx_fNotesErr",    max: 2000, label: "Ghi chú" }
};

scwin.EVENT_STATUS_CLASS = {
    DRAFT: "hm-ev-status--draft", ACTIVE: "hm-ev-status--active",
    COMPLETED: "hm-ev-status--done", CANCELLED: "hm-ev-status--cancel", CANCELED: "hm-ev-status--cancel"
};

/* =====================================================================
 * VÒNG ĐỜI TRANG
 * ===================================================================== */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }

    scwin.initFileInput();
    scwin.initDropzone();

    scwin.keyHandler = function (e) { scwin.onGlobalKeydown(e); };
    scwin.pasteHandler = function (e) { scwin.onGlobalPaste(e); };
    document.addEventListener("keydown", scwin.keyHandler);
    document.addEventListener("paste", scwin.pasteHandler);

    dma_search.setJSON(scwin.SEARCH_DEFAULT);      // ô tìm kiếm, sắp xếp, số dòng tự cập nhật theo binding
    scwin.applyStatusSegment();
    scwin.applyPermissions();

    scwin.loadStats();
    scwin.search(true);
};

scwin.onpageunload = function () {
    document.removeEventListener("keydown", scwin.keyHandler);
    document.removeEventListener("paste", scwin.pasteHandler);
    scwin.revokePreview();
    if (scwin.fileInput && scwin.fileInput.parentNode) scwin.fileInput.parentNode.removeChild(scwin.fileInput);
};

/* ---------- Ẩn / hiện nút theo quyền ----------
 * Chỉ để giao diện gọn hơn; backend vẫn kiểm tra quyền và trả 403 nếu thiếu.
 * Nếu Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm hiện đủ nút.
 */
scwin.applyPermissions = function () {
    var perms = scwin.getPerms();
    if (!perms.length) return;
    var canManage = perms.indexOf("HALL_MANAGE") >= 0;
    var canDelete = perms.indexOf("HALL_DELETE") >= 0;
    scwin.show(btn_add, canManage);
    scwin.show(btn_emptyAdd, canManage);
    scwin.show(btn_dEdit, canManage);
    scwin.show(btn_dDelete, canDelete);
    scwin.canManage = canManage;
};

/* =====================================================================
 * TIỆN ÍCH CHUNG
 * ===================================================================== */
scwin.comp = function (id) { return $p.getComponentById(id); };

scwin.domOf = function (comp) {
    if (!comp) return null;
    return comp.render || document.getElementById(comp.id) || null;
};

scwin.show = function (comp, visible) {
    if (!comp) return;
    if (visible === false) comp.addClass("is-hidden"); else comp.removeClass("is-hidden");
};

scwin.toggleClass = function (comp, cls, on) {
    if (!comp) return;
    if (on) comp.addClass(cls); else comp.removeClass(cls);
};

scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };

scwin.fmtNumber = function (n) {
    if (n == null || n === "" || isNaN(Number(n))) return "—";
    return Number(n).toLocaleString("vi-VN");
};

scwin.fmtDate = function (s) {               // "2026-09-20" -> "20/09/2026"
    if (!s) return "";
    var p = String(s).substring(0, 10).split("-");
    return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s);
};

scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };   // "08:00:00" -> "08:00"

scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear()
         + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};

scwin.fmtSize = function (bytes) {
    if (bytes >= 1024 * 1024) return (bytes / 1024 / 1024).toFixed(1) + " MB";
    return Math.max(1, Math.round(bytes / 1024)) + " KB";
};

scwin.initials = function (name) {
    var words = scwin.trim(name).split(/\s+/).filter(function (w) { return w.length > 0; });
    if (!words.length) return "H";
    var last = words.slice(-2);
    return last.map(function (w) { return w.charAt(0); }).join("").toUpperCase();
};

scwin.buildQuery = function (params) {
    var parts = [];
    for (var k in params) {
        if (!params.hasOwnProperty(k)) continue;
        var v = params[k];
        if (v === null || v === undefined || v === "") continue;
        parts.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return parts.join("&");
};

/* =====================================================================
 * FORMATTER CỦA GRID (customFormatter: data, formattedData, rowIndex, colIndex)
 * dataList giữ dữ liệu gốc từ API; phần hiển thị định dạng tại đây.
 * ===================================================================== */
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

scwin.gfDash = function (v) { return scwin.dash(v); };
scwin.gfCapacity = function (v) { return (v == null || v === "") ? "—" : scwin.fmtNumber(v) + " chỗ"; };
scwin.gfActive = function (v) { return scwin.isTrue(v) ? "● Hoạt động" : "● Ngưng"; };
scwin.gfImage = function (v) { return v ? "Có ảnh" : "—"; };
scwin.gfDateTime = function (v) { return scwin.fmtDateTime(v); };

scwin.gfEventTime = function (v, f, rowIndex) {
    var e = dlt_event.getRowJSON(rowIndex) || {};
    var d1 = scwin.fmtDate(e.startDate), d2 = scwin.fmtDate(e.endDate);
    var date = (d2 && d2 !== d1) ? d1 + " – " + d2 : d1;
    var time = e.startTime ? scwin.fmtTime(e.startTime) + (e.endTime ? "–" + scwin.fmtTime(e.endTime) : "") : "";
    return time ? date + ", " + time : date;
};
scwin.gfEventStatus = function (v, f, rowIndex) {
    return v || (dlt_event.getRowJSON(rowIndex) || {}).statusCode || "—";
};
scwin.gfCheckin = function (v, f, rowIndex) {
    var e = dlt_event.getRowJSON(rowIndex) || {};
    var total = Number(e.totalGuests) || 0, checked = Number(e.checkedInCount) || 0;
    return total > 0 ? scwin.fmtNumber(checked) + " (" + Math.round(checked * 100 / total) + "%)" : "—";
};

/* =====================================================================
 * GỌI API
 * ===================================================================== */
scwin.storeGet = function (key) {
    try { return window.localStorage.getItem(key) || window.sessionStorage.getItem(key) || ""; }
    catch (e) { return ""; }
};

/** JWT lấy từ phiên đăng nhập, bỏ tiền tố "Bearer " nếu có. */
scwin.getToken = function () {
    return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, "");
};

/** Danh sách mã quyền Header đã lưu sau khi gọi /api/common/layout. */
scwin.getPerms = function () {
    try { return JSON.parse(scwin.storeGet(scwin.KEY.PERMS) || "[]") || []; }
    catch (e) { return []; }
};

scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try {
            window.localStorage.removeItem(scwin.KEY[k]);
            window.sessionStorage.removeItem(scwin.KEY[k]);
        } catch (e) { }
    }
    window.location.href = scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + scwin.LOGIN_PAGE;
};

scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy hội trường. Có thể hội trường đã bị xóa.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};

/** Header gửi kèm mọi request: JWT của phiên đăng nhập. */
scwin.authHeader = function () {
    var h = { "Accept": "application/json" };
    var token = scwin.getToken();
    if (token) h["Authorization"] = "Bearer " + token;
    return h;
};

scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };

scwin.parseJSON = function (text) {
    if (!text || typeof text !== "string") return null;
    try { return JSON.parse(text); } catch (e) { return null; }
};

/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* =====================================================================
 * SUBMISSION (WebSquare)
 *   scwin.callApi("sbm_xxx", { path: "/3/events?page=0", body: {...} })
 *   -> Promise<data>  (data = trường "data" trong response của backend)
 *
 *   - Mỗi submission có hàng đợi riêng: gọi chồng nhau thì chạy lần lượt,
 *     nên phản hồi không bao giờ bị trả nhầm cho lời gọi khác.
 *   - action = HALL_API + path; GET truyền tham số qua query string;
 *     POST/PUT truyền body qua requestData của $p.executeSubmission.
 * ===================================================================== */
scwin.SBM_TIMEOUT = 30000;
scwin.sbmQueue = {};
scwin.sbmJob = {};

scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};

scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var queue = scwin.sbmQueue[sbmId];
    if (!queue || !queue.length) return;

    var job = queue.shift();
    scwin.sbmJob[sbmId] = job;

    var sbm = $p.getSubmission(sbmId);
    if (!sbm) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." });
        return;
    }
    sbm.action = scwin.HALL_API + (job.opts.path || "");
    sbm.requestHeader = scwin.authHeader();

    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);

    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};

scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};

scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};

scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) {
        scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json));
        return;
    }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};

scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* Handler gắn trong xf:submission (ev:submitdone / ev:submiterror) */
scwin.sbm_hallList_submitdone  = function (e) { scwin.onSbmDone("sbm_hallList", e); };
scwin.sbm_hallList_submiterror = function (e) { scwin.onSbmError("sbm_hallList", e); };
scwin.sbm_hallStats_submitdone  = function (e) { scwin.onSbmDone("sbm_hallStats", e); };
scwin.sbm_hallStats_submiterror = function (e) { scwin.onSbmError("sbm_hallStats", e); };
scwin.sbm_hallNameCheck_submitdone  = function (e) { scwin.onSbmDone("sbm_hallNameCheck", e); };
scwin.sbm_hallNameCheck_submiterror = function (e) { scwin.onSbmError("sbm_hallNameCheck", e); };
scwin.sbm_hallDetail_submitdone  = function (e) { scwin.onSbmDone("sbm_hallDetail", e); };
scwin.sbm_hallDetail_submiterror = function (e) { scwin.onSbmError("sbm_hallDetail", e); };
scwin.sbm_hallEvents_submitdone  = function (e) { scwin.onSbmDone("sbm_hallEvents", e); };
scwin.sbm_hallEvents_submiterror = function (e) { scwin.onSbmError("sbm_hallEvents", e); };
scwin.sbm_hallCreate_submitdone  = function (e) { scwin.onSbmDone("sbm_hallCreate", e); };
scwin.sbm_hallCreate_submiterror = function (e) { scwin.onSbmError("sbm_hallCreate", e); };
scwin.sbm_hallUpdate_submitdone  = function (e) { scwin.onSbmDone("sbm_hallUpdate", e); };
scwin.sbm_hallUpdate_submiterror = function (e) { scwin.onSbmError("sbm_hallUpdate", e); };
scwin.sbm_hallDelete_submitdone  = function (e) { scwin.onSbmDone("sbm_hallDelete", e); };
scwin.sbm_hallDelete_submiterror = function (e) { scwin.onSbmError("sbm_hallDelete", e); };
scwin.sbm_hallImageDelete_submitdone  = function (e) { scwin.onSbmDone("sbm_hallImageDelete", e); };
scwin.sbm_hallImageDelete_submiterror = function (e) { scwin.onSbmError("sbm_hallImageDelete", e); };

/* =====================================================================
 * UPLOAD ẢNH (multipart/form-data)
 * Submission chỉ gửi JSON/XML, không gửi được file nhị phân, nên riêng
 * phần upload dùng XMLHttpRequest. Có báo tiến độ tải lên.
 * ===================================================================== */
scwin.uploadImage = function (hallId, file, onProgress) {
    return new Promise(function (resolve, reject) {
        var xhr = new XMLHttpRequest();
        xhr.open("POST", scwin.HALL_API + "/" + hallId + "/image");
        var h = scwin.authHeader();
        for (var k in h) if (h.hasOwnProperty(k)) xhr.setRequestHeader(k, h[k]);

        if (xhr.upload && onProgress) {
            xhr.upload.onprogress = function (ev) {
                if (ev.lengthComputable) onProgress(Math.round(ev.loaded * 100 / ev.total));
            };
        }
        xhr.onload = function () {
            var json = scwin.parseJSON(xhr.responseText);
            if (xhr.status >= 200 && xhr.status < 300 && !(json && json.success === false)) {
                resolve(scwin.hasOwn(json, "data") ? json.data : json);
            } else {
                reject(scwin.buildError(xhr.status, json));
            }
        };
        xhr.onerror = function () { reject(scwin.buildError(0, null)); };

        var fd = new FormData();
        fd.append("file", file);
        xhr.send(fd);
    });
};

/* =====================================================================
 * THỐNG KÊ TRẠNG THÁI (hiển thị ngay trên bộ lọc)
 * ===================================================================== */
scwin.loadStats = function () {
    var count = function (active) {
        var p = { page: 0, size: 1 };
        if (active !== null) p.active = active;
        return scwin.callApi("sbm_hallStats", { path: "?" + scwin.buildQuery(p) }).then(function (pg) {
            return pg && pg.totalElements != null ? pg.totalElements : 0;
        });
    };
    Promise.all([count(null), count(true), count(false)]).then(function (r) {
        tbx_segAllCount.setValue(scwin.fmtNumber(r[0]));
        tbx_segOnCount.setValue(scwin.fmtNumber(r[1]));
        tbx_segOffCount.setValue(scwin.fmtNumber(r[2]));
    }).catch(function () {
        tbx_segAllCount.setValue("—");
        tbx_segOnCount.setValue("—");
        tbx_segOffCount.setValue("—");
    });
};

/* =====================================================================
 * TÌM KIẾM & DANH SÁCH
 * ===================================================================== */
/** Đồng bộ ô đang gõ vào dataMap (dự phòng khi bản WebSquare không hỗ trợ refSync). */
scwin.syncSearchInputs = function () {
    var pairs = [["keyword", ibx_keyword], ["minCapacity", ibx_minCap], ["maxCapacity", ibx_maxCap]];
    for (var i = 0; i < pairs.length; i++) {
        var v = pairs[i][1].getValue();
        if (dma_search.get(pairs[i][0]) !== v) dma_search.set(pairs[i][0], v);
    }
};

/** Lấy điều kiện từ dma_search, kiểm tra khoảng sức chứa. Trả null nếu không hợp lệ. */
scwin.collectFilter = function () {
    var q = dma_search.getJSON();
    var min = scwin.trim(q.minCapacity), max = scwin.trim(q.maxCapacity);

    if (min !== "" && max !== "" && parseInt(min, 10) > parseInt(max, 10)) {
        tbx_capErr.setValue("Sức chứa tối thiểu đang lớn hơn tối đa. Hãy đổi lại khoảng.");
        scwin.show(tbx_capErr, true);
        grp_capRange.addClass("is-invalid");
        return null;
    }
    scwin.show(tbx_capErr, false);
    grp_capRange.removeClass("is-invalid");

    return {
        keyword: scwin.trim(q.keyword), minCapacity: min, maxCapacity: max,
        active: q.active, page: q.page || 0, size: q.size || 10, sort: q.sort || "hallId,desc"
    };
};

scwin.hasFilter = function () {
    var q = dma_search.getJSON();
    return !!(scwin.trim(q.keyword) || scwin.trim(q.minCapacity) || scwin.trim(q.maxCapacity) || q.active);
};

scwin.search = function (resetPage) {
    if (resetPage) dma_search.set("page", "0");
    var params = scwin.collectFilter();
    if (!params) return;

    scwin.updateFilterSummary(params);
    var seq = ++scwin.searchSeq;
    grp_listBody.addClass("is-loading");

    scwin.callApi("sbm_hallList", { path: "?" + scwin.buildQuery(params) }).then(function (page) {
        if (seq !== scwin.searchSeq) return;
        scwin.renderList(page || {});
    }).catch(function (err) {
        if (seq !== scwin.searchSeq) return;
        scwin.renderList({ content: [], totalElements: 0, totalPages: 0 });
        if (err.code === "INVALID_CAPACITY_RANGE") {
            tbx_capErr.setValue(err.message);
            scwin.show(tbx_capErr, true);
        } else {
            scwin.toast(err.message, "error");
        }
    }).then(function () {
        if (seq === scwin.searchSeq) grp_listBody.removeClass("is-loading");
    });
};

scwin.renderList = function (page) {
    var content = page.content || [];
    var curPage = parseInt(dma_search.get("page"), 10) || 0;
    var size = parseInt(dma_search.get("size"), 10) || 10;
    scwin.state.totalPages = page.totalPages || 0;
    scwin.state.totalElements = page.totalElements || 0;

    // Trang hiện tại trống (vd: vừa xóa phần tử cuối) -> lùi về trang cuối hợp lệ
    if (!content.length && curPage > 0 && scwin.state.totalPages > 0) {
        dma_search.set("page", String(scwin.state.totalPages - 1));
        scwin.search(false);
        return;
    }

    dlt_hall.setJSON(content);                       // grid tự hiển thị qua binding + customFormatter

    for (var i = 0; i < content.length; i++) {
        try {
            grd_hall.setCellClass(i, "active", content[i].active ? "hm-cell-on" : "hm-cell-off");
        } catch (e) { /* phiên bản grid không hỗ trợ setCellClass */ }
    }

    var empty = content.length === 0;
    scwin.show(grp_empty, empty);
    scwin.toggleClass(grp_listBody, "is-empty", empty);
    if (empty) {
        var filtered = scwin.hasFilter();
        tbx_emptyTitle.setValue(filtered ? "Không có hội trường khớp bộ lọc" : "Chưa có hội trường nào");
        tbx_emptyDesc.setValue(filtered
            ? "Thử bớt điều kiện lọc hoặc tìm bằng từ khóa khác."
            : "Thêm hội trường đầu tiên để bắt đầu gán địa điểm cho sự kiện.");
        scwin.show(btn_emptyReset, filtered);
        scwin.show(btn_emptyAdd, !filtered && scwin.canManage !== false);
    }

    var from = empty ? 0 : curPage * size + 1;
    var to = empty ? 0 : from + content.length - 1;
    tbx_resultInfo.setValue(empty
        ? "Không có kết quả"
        : "Hiển thị " + from + "–" + to + " trong " + scwin.fmtNumber(scwin.state.totalElements) + " hội trường");

    scwin.pagingLock = true;
    try {
        pgl_hall.setCount(Math.max(scwin.state.totalPages, 1));
        pgl_hall.setSelectedIndex(curPage + 1);
    } catch (e) { }
    scwin.pagingLock = false;
    scwin.show(grp_pager, scwin.state.totalPages > 1);
};

scwin.updateFilterSummary = function (p) {
    var parts = [];
    if (p.keyword) parts.push("“" + p.keyword + "”");
    if (p.minCapacity && p.maxCapacity) parts.push("sức chứa " + p.minCapacity + "–" + p.maxCapacity);
    else if (p.minCapacity) parts.push("sức chứa từ " + p.minCapacity);
    else if (p.maxCapacity) parts.push("sức chứa đến " + p.maxCapacity);
    if (p.active === "true") parts.push("đang hoạt động");
    if (p.active === "false") parts.push("ngưng hoạt động");

    tbx_filterSummary.setValue(parts.length ? "Đang lọc: " + parts.join(", ") : "");
    scwin.show(tbx_filterSummary, parts.length > 0);
    scwin.show(btn_reset, parts.length > 0);
};

/* ---------- Sự kiện bộ lọc ---------- */
scwin.ibx_keyword_onkeyup = function (e) {
    scwin.syncSearchInputs();
    clearTimeout(scwin.searchTimer);
    if (e && e.keyCode === 13) { scwin.search(true); return; }
    scwin.searchTimer = setTimeout(function () { scwin.search(true); }, 400);
};

scwin.ibx_cap_onkeyup = function (e) {
    scwin.syncSearchInputs();
    clearTimeout(scwin.searchTimer);
    if (e && e.keyCode === 13) { scwin.search(true); return; }
    scwin.searchTimer = setTimeout(function () { scwin.search(true); }, 550);
};

scwin.setStatusFilter = function (val) {
    if (dma_search.get("active") === val) return;
    dma_search.set("active", val);
    scwin.applyStatusSegment();
    scwin.search(true);
};

scwin.applyStatusSegment = function () {
    var a = dma_search.get("active") || "";
    scwin.toggleClass(grp_segAll, "is-selected", a === "");
    scwin.toggleClass(grp_segOn, "is-selected", a === "true");
    scwin.toggleClass(grp_segOff, "is-selected", a === "false");
};

scwin.grp_segAll_onclick = function () { scwin.setStatusFilter(""); };
scwin.grp_segOn_onclick = function () { scwin.setStatusFilter("true"); };
scwin.grp_segOff_onclick = function () { scwin.setStatusFilter("false"); };

scwin.sbx_sort_onchange = function () {
    dma_search.set("sort", sbx_sort.getValue() || "hallId,desc");
    scwin.search(true);
};

scwin.sbx_size_onchange = function () {
    dma_search.set("size", sbx_size.getValue() || "10");
    scwin.search(true);
};

scwin.btn_reset_onclick = function () {
    var q = dma_search.getJSON();
    dma_search.setJSON({                      // giữ sắp xếp và số dòng, xóa các điều kiện lọc
        keyword: "", minCapacity: "", maxCapacity: "", active: "",
        sort: q.sort || "hallId,desc", size: q.size || "10", page: "0"
    });
    scwin.applyStatusSegment();
    scwin.search(true);
};
scwin.btn_emptyReset_onclick = scwin.btn_reset_onclick;

scwin.btn_refresh_onclick = function () {
    scwin.loadStats();
    scwin.search(false);
};

scwin.pgl_hall_onviewchange = function (info) {
    if (scwin.pagingLock) return;
    var idx = (info && info.newSelectedIndex) ? info.newSelectedIndex : pgl_hall.getSelectedIndex();
    dma_search.set("page", String(Math.max(0, idx - 1)));
    scwin.search(false);
};

scwin.grd_hall_oncellclick = function (rowIndex) {
    var row = dlt_hall.getRowJSON(rowIndex);
    if (row && row.hallId) scwin.openDetail(row.hallId);
};

/* =====================================================================
 * PANEL CHI TIẾT
 * ===================================================================== */
scwin.openDetail = function (hallId) {
    scwin.drawerOpen = true;
    grp_drawerMask.addClass("is-open");
    grp_drawer.addClass("is-open");
    grp_drawer.addClass("is-loading");

    scwin.callApi("sbm_hallDetail", { path: "/" + hallId }).then(function (hall) {
        scwin.renderDetail(hall);
        scwin.loadEvents(true);
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        if (err.status === 404) {
            scwin.closeDrawer();
            scwin.search(false);
            scwin.loadStats();
        }
    }).then(function () {
        grp_drawer.removeClass("is-loading");
    });
};

scwin.renderDetail = function (h) {
    scwin.current = h;
    tbx_dName.setValue(h.hallName || "");
    tbx_dCode.setValue(h.hallCode || "");
    tbx_dStatus.setValue(h.active ? "Đang hoạt động" : "Ngưng hoạt động");
    scwin.toggleClass(tbx_dStatus, "is-on", !!h.active);
    scwin.toggleClass(tbx_dStatus, "is-off", !h.active);

    tbx_dCapacity.setValue(h.capacity == null ? "Chưa khai báo" : scwin.fmtNumber(h.capacity) + " chỗ ngồi");
    tbx_dFloor.setValue(scwin.dash(h.floorArea));
    tbx_dAddress.setValue(scwin.dash(h.address));
    tbx_dDesc.setValue(h.description ? h.description : "Chưa có mô tả tiện nghi.");
    scwin.toggleClass(tbx_dDesc, "is-placeholder", !h.description);
    tbx_dNotes.setValue(h.notes ? h.notes : "Không có ghi chú.");
    scwin.toggleClass(tbx_dNotes, "is-placeholder", !h.notes);
    tbx_dCreated.setValue("Tạo lúc " + scwin.fmtDateTime(h.createdAt));
    tbx_dUpdated.setValue("Cập nhật lúc " + scwin.fmtDateTime(h.updatedAt));

    tbx_dInitial.setValue(scwin.initials(h.hallName));
    if (h.imageUrl) {
        grp_dCover.setStyle("background-image", "url(\"" + h.imageUrl + "\")");
        grp_dCover.addClass("has-image");
    } else {
        grp_dCover.setStyle("background-image", "none");
        grp_dCover.removeClass("has-image");
    }
};

scwin.loadEvents = function (reset) {
    if (!scwin.current) return;
    if (reset) {
        scwin.ev = { page: 0, items: [], totalPages: 0, totalElements: 0, loading: false };
        dlt_event.setJSON([]);
        tbx_evCount.setValue("Đang tải…");
        scwin.show(grp_evEmpty, false);
        scwin.show(btn_evMore, false);
    }
    if (scwin.ev.loading) return;

    var hallId = scwin.current.hallId;
    var evState = scwin.ev;
    evState.loading = true;
    btn_evMore.addClass("is-busy");
    grp_evWrap.addClass("is-loading");

    var q = scwin.buildQuery({ page: evState.page, size: scwin.EVENT_PAGE_SIZE });
    scwin.callApi("sbm_hallEvents", { path: "/" + hallId + "/events?" + q }).then(function (page) {
        if (!scwin.current || scwin.current.hallId !== hallId || scwin.ev !== evState) return;
        evState.items = evState.items.concat((page && page.content) || []);
        evState.totalPages = (page && page.totalPages) || 0;
        evState.totalElements = (page && page.totalElements) || 0;
        evState.page += 1;
        scwin.renderEvents();
    }).catch(function (err) {
        tbx_evCount.setValue("Không tải được lịch sử sự kiện");
        scwin.toast(err.message, "error");
    }).then(function () {
        evState.loading = false;
        btn_evMore.removeClass("is-busy");
        grp_evWrap.removeClass("is-loading");
    });
};

scwin.renderEvents = function () {
    var items = scwin.ev.items;
    dlt_event.setJSON(items);                        // grid định dạng qua customFormatter

    for (var i = 0; i < items.length; i++) {
        try {
            grd_event.setCellClass(i, "statusName", "hm-ev-status " + (scwin.EVENT_STATUS_CLASS[items[i].statusCode] || ""));
        } catch (e) { }
    }

    grd_event.setStyle("height", (items.length ? 42 + items.length * 48 : 0) + "px");
    scwin.show(grd_event, items.length > 0);
    scwin.show(grp_evEmpty, items.length === 0);

    tbx_evCount.setValue(scwin.ev.totalElements
        ? scwin.fmtNumber(scwin.ev.totalElements) + " sự kiện, mới nhất trước"
        : "Chưa tổ chức sự kiện nào");
    scwin.show(btn_evMore, scwin.ev.page < scwin.ev.totalPages);
};

scwin.btn_evMore_onclick = function () { scwin.loadEvents(false); };

scwin.closeDrawer = function () {
    scwin.drawerOpen = false;
    grp_drawerMask.removeClass("is-open");
    grp_drawer.removeClass("is-open");
};
scwin.grp_drawerMask_onclick = scwin.closeDrawer;
scwin.btn_dClose_onclick = scwin.closeDrawer;

scwin.btn_dEdit_onclick = function () {
    if (scwin.current) scwin.openForm("update", scwin.current);
};

scwin.btn_dDelete_onclick = function () { scwin.openDelete(); };

/* =====================================================================
 * FORM TẠO / SỬA
 * ===================================================================== */
scwin.btn_add_onclick = function () { scwin.openForm("create", null); };
scwin.btn_emptyAdd_onclick = scwin.btn_add_onclick;

scwin.openForm = function (mode, hall) {
    var f = scwin.form;
    f.mode = mode;
    f.hallId = hall ? hall.hallId : null;
    f.originalName = hall ? (hall.hallName || "") : "";
    f.active = hall ? hall.active !== false : true;
    f.file = null;
    f.removeImage = false;
    f.originalImage = hall ? hall.imageUrl : null;
    f.dirty = false;
    f.saving = false;
    scwin.revokePreview();

    tbx_fTitle.setValue(mode === "create" ? "Thêm hội trường" : "Sửa hội trường");
    tbx_fSubtitle.setValue(mode === "create"
        ? "Chỉ tên hội trường là bắt buộc. Các thông tin khác có thể bổ sung sau."
        : "Đang sửa " + (hall.hallCode || "") + ". Lần cập nhật gần nhất: " + scwin.fmtDateTime(hall.updatedAt) + ".");

    // Điền form: chỉ cần setJSON, các ô nhập tự cập nhật theo binding
    var h = hall || {};
    dma_hallForm.setJSON({
        hallName: h.hallName || "", hallCode: h.hallCode || "",
        capacity: h.capacity != null ? String(h.capacity) : "",
        address: h.address || "", floorArea: h.floorArea || "",
        description: h.description || "", notes: h.notes || ""
    });

    tbx_fCodeHint.setValue(mode === "create"
        ? "Bỏ trống để hệ thống tự sinh mã (HALL0001, HALL0002…)."
        : "Bỏ trống để giữ nguyên mã hiện tại.");

    scwin.clearFormErrors();
    scwin.applyActiveSegment();
    scwin.renderPreview(f.originalImage, f.originalImage ? "Ảnh hiện tại" : "");
    scwin.updateCounters();
    scwin.show(tbx_fNameHint, false);

    scwin.formOpen = true;
    grp_formMask.addClass("is-open");
    setTimeout(function () { try { ibx_fName.focus(); } catch (e) { } }, 150);
};

scwin.closeForm = function (force) {
    if (!force && scwin.form.dirty && !window.confirm("Thông tin vừa nhập chưa được lưu. Đóng biểu mẫu?")) return;
    clearTimeout(scwin.dupTimer);
    scwin.formOpen = false;
    grp_formMask.removeClass("is-open");
    scwin.revokePreview();
};
scwin.btn_fClose_onclick = function () { scwin.closeForm(false); };
scwin.btn_fCancel_onclick = function () { scwin.closeForm(false); };

scwin.markDirty = function () { scwin.form.dirty = true; };

/** Dự phòng khi bản WebSquare không hỗ trợ refSync: đẩy giá trị các ô nhập vào dma_hallForm. */
scwin.syncFormInputs = function () {
    for (var k in scwin.FIELDS) {
        if (!scwin.FIELDS.hasOwnProperty(k)) continue;
        var v = scwin.comp(scwin.FIELDS[k].input).getValue();
        if (dma_hallForm.get(k) !== v) dma_hallForm.set(k, v);
    }
};

/** Đọc form từ dma_hallForm (đã trim). */
scwin.readForm = function () {
    var raw = dma_hallForm.getJSON(), v = {};
    for (var k in scwin.FIELDS) {
        if (scwin.FIELDS.hasOwnProperty(k)) v[k] = scwin.trim(raw[k]);
    }
    return v;
};

scwin.validateForm = function (v) {
    var errs = {};
    if (!v.hallName) errs.hallName = "Nhập tên hội trường.";
    if (v.hallCode && !/^[A-Za-z0-9._-]+$/.test(v.hallCode)) errs.hallCode = "Mã chỉ gồm chữ, số và các ký tự . _ -";
    if (v.capacity !== "" && (!/^\d+$/.test(v.capacity) || parseInt(v.capacity, 10) <= 0)) {
        errs.capacity = "Sức chứa phải là số nguyên lớn hơn 0.";
    }
    for (var k in scwin.FIELDS) {
        var f = scwin.FIELDS[k];
        if (!errs[k] && f.max && v[k].length > f.max) errs[k] = f.label + " tối đa " + f.max + " ký tự (hiện " + v[k].length + ").";
    }
    return errs;
};

scwin.showFieldError = function (key, msg) {
    var f = scwin.FIELDS[key];
    if (!f) return false;
    var err = scwin.comp(f.error);
    err.setValue(msg);
    scwin.show(err, true);
    scwin.comp(f.input).addClass("is-invalid");
    return true;
};

scwin.clearFieldError = function (key) {
    var f = scwin.FIELDS[key];
    if (!f) return;
    scwin.show(scwin.comp(f.error), false);
    scwin.comp(f.input).removeClass("is-invalid");
};

scwin.clearFormErrors = function () {
    for (var k in scwin.FIELDS) if (scwin.FIELDS.hasOwnProperty(k)) scwin.clearFieldError(k);
    scwin.show(tbx_fAlert, false);
    scwin.show(tbx_fImgErr, false);
};

scwin.focusField = function (key) {
    var f = scwin.FIELDS[key];
    if (f) { try { scwin.comp(f.input).focus(); } catch (e) { } }
};

scwin.btn_fSave_onclick = function () {
    var f = scwin.form;
    if (f.saving) return;
    scwin.clearFormErrors();
    scwin.syncFormInputs();

    var v = scwin.readForm();
    var errs = scwin.validateForm(v);
    var keys = Object.keys(errs);
    if (keys.length) {
        keys.forEach(function (k) { scwin.showFieldError(k, errs[k]); });
        scwin.focusField(keys[0]);
        return;
    }

    var body = {
        hallName: v.hallName,
        hallCode: v.hallCode ? v.hallCode.toUpperCase() : null,
        address: v.address || null,
        floorArea: v.floorArea || null,
        capacity: v.capacity === "" ? null : parseInt(v.capacity, 10),
        description: v.description || null,
        active: f.active,
        notes: v.notes || null
    };

    var mode = f.mode;
    scwin.setSaving(true);
    var req = mode === "create"
        ? scwin.callApi("sbm_hallCreate", { path: "", body: body })
        : scwin.callApi("sbm_hallUpdate", { path: "/" + f.hallId, body: body });

    req.then(function (hall) {
        return scwin.syncImage(hall);
    }).then(function (hall) {
        scwin.form.dirty = false;
        scwin.closeForm(true);
        scwin.toast(mode === "create"
            ? "Đã tạo hội trường " + hall.hallName + " (" + hall.hallCode + ")."
            : "Đã lưu thay đổi cho " + hall.hallName + ".", "success");
        if (mode === "create") dma_search.set("page", "0");
        scwin.search(false);
        scwin.loadStats();
        if (scwin.drawerOpen && scwin.current && scwin.current.hallId === hall.hallId) scwin.renderDetail(hall);
    }).catch(function (err) {
        scwin.handleFormError(err);
    }).then(function () {
        scwin.setSaving(false);
    });
};

/** Sau khi lưu thông tin: upload ảnh mới hoặc gỡ ảnh cũ. Không bao giờ reject. */
scwin.syncImage = function (hall) {
    var f = scwin.form;
    var warn = function (err) {
        scwin.toast("Đã lưu thông tin nhưng chưa cập nhật được ảnh: " + err.message, "warning");
        return hall;
    };
    if (f.file) {
        return scwin.uploadImage(hall.hallId, f.file, function (pct) {
            tbx_fImgName.setValue("Đang tải ảnh lên… " + pct + "%");
        }).catch(warn);
    }
    if (f.removeImage && hall.imageUrl) {
        return scwin.callApi("sbm_hallImageDelete", { path: "/" + hall.hallId + "/image" }).catch(warn);
    }
    return Promise.resolve(hall);
};

scwin.handleFormError = function (err) {
    var shown = false, firstKey = null;
    if (err.code === "VALIDATION_ERROR" && err.data && typeof err.data === "object") {
        for (var k in err.data) {
            if (err.data.hasOwnProperty(k) && scwin.showFieldError(k, err.data[k])) {
                shown = true;
                if (!firstKey) firstKey = k;
            }
        }
    } else if (err.code === "HALL_NAME_EXISTS") {
        shown = scwin.showFieldError("hallName", err.message || "Tên hội trường đã tồn tại.");
        firstKey = "hallName";
    } else if (err.code === "HALL_CODE_EXISTS") {
        shown = scwin.showFieldError("hallCode", err.message || "Mã hội trường đã tồn tại.");
        firstKey = "hallCode";
    } else if (err.code === "HALL_NOT_FOUND") {
        scwin.closeForm(true);
        scwin.closeDrawer();
        scwin.toast(err.message, "error");
        scwin.search(false);
        scwin.loadStats();
        return;
    }
    if (firstKey) scwin.focusField(firstKey);
    if (!shown) {
        tbx_fAlert.setValue(err.message || "Không lưu được hội trường.");
        scwin.show(tbx_fAlert, true);
    }
};

scwin.setSaving = function (on) {
    scwin.form.saving = on;
    scwin.toggleClass(btn_fSave, "is-busy", on);
    try { btn_fSave.setDisabled(on); btn_fCancel.setDisabled(on); } catch (e) { }
};

/* ---------- Trạng thái Active / Inactive trong form ---------- */
scwin.applyActiveSegment = function () {
    scwin.toggleClass(btn_fActive, "is-selected", scwin.form.active);
    scwin.toggleClass(btn_fInactive, "is-selected", !scwin.form.active);
    tbx_fActiveHint.setValue(scwin.form.active
        ? "Hội trường xuất hiện trong danh sách chọn địa điểm khi tạo sự kiện."
        : "Ẩn khỏi danh sách chọn địa điểm. Sự kiện cũ vẫn giữ nguyên.");
};
scwin.btn_fActive_onclick = function () { if (!scwin.form.active) { scwin.form.active = true; scwin.markDirty(); scwin.applyActiveSegment(); } };
scwin.btn_fInactive_onclick = function () { if (scwin.form.active) { scwin.form.active = false; scwin.markDirty(); scwin.applyActiveSegment(); } };

/* ---------- Kiểm tra trùng tên ngay khi gõ ---------- */
scwin.ibx_fName_onkeyup = function (e) {
    scwin.markDirty();
    scwin.clearFieldError("hallName");
    clearTimeout(scwin.dupTimer);
    var name = scwin.trim(ibx_fName.getValue());
    if (dma_hallForm.get("hallName") !== ibx_fName.getValue()) dma_hallForm.set("hallName", ibx_fName.getValue());
    if (!name) { scwin.show(tbx_fNameHint, false); return; }
    scwin.dupTimer = setTimeout(function () { scwin.checkNameDup(name); }, 450);
};

scwin.checkNameDup = function (name) {
    var f = scwin.form;
    if (f.mode === "update" && name.toLowerCase() === f.originalName.toLowerCase()) {
        scwin.show(tbx_fNameHint, false);
        return;
    }
    scwin.callApi("sbm_hallNameCheck", { path: "?" + scwin.buildQuery({ hallName: name, page: 0, size: 20 }) }).then(function (page) {
        if (!scwin.formOpen || scwin.trim(ibx_fName.getValue()) !== name) return;
        var dup = ((page && page.content) || []).some(function (h) {
            return scwin.trim(h.hallName).toLowerCase() === name.toLowerCase() && h.hallId !== f.hallId;
        });
        tbx_fNameHint.setValue(dup ? "Tên này đang được một hội trường khác sử dụng." : "Tên chưa bị trùng.");
        scwin.toggleClass(tbx_fNameHint, "is-warning", dup);
        scwin.toggleClass(tbx_fNameHint, "is-ok", !dup);
        scwin.show(tbx_fNameHint, true);
    }).catch(function () {
        scwin.show(tbx_fNameHint, false);
    });
};

scwin.ibx_fCode_onblur = function () {
    dma_hallForm.set("hallCode", scwin.trim(dma_hallForm.get("hallCode")).toUpperCase());
};

scwin.field_onkeyup = function () { scwin.markDirty(); };
scwin.ibx_fCode_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("hallCode"); };
scwin.ibx_fCapacity_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("capacity"); };
scwin.ibx_fAddress_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("address"); };
scwin.ibx_fFloor_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("floorArea"); };
scwin.txa_fDesc_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("description"); scwin.updateCounters(); };
scwin.txa_fNotes_onkeyup = function () { scwin.markDirty(); scwin.clearFieldError("notes"); scwin.updateCounters(); };

scwin.updateCounters = function () {
    var d = (txa_fDesc.getValue() || "").length, n = (txa_fNotes.getValue() || "").length;
    tbx_fDescCount.setValue(scwin.fmtNumber(d) + " / 4.000");
    tbx_fNotesCount.setValue(scwin.fmtNumber(n) + " / 2.000");
    scwin.toggleClass(tbx_fDescCount, "is-over", d > 4000);
    scwin.toggleClass(tbx_fNotesCount, "is-over", n > 2000);
};

/* ---------- Hình ảnh: chọn, kéo thả, dán (Ctrl+V) ---------- */
scwin.initFileInput = function () {
    var inp = document.createElement("input");
    inp.type = "file";
    inp.accept = scwin.IMAGE_TYPES.join(",");
    inp.className = "hm-native-file";
    inp.addEventListener("change", function () {
        var file = inp.files && inp.files[0];
        inp.value = "";
        if (file) scwin.acceptFile(file);
    });
    document.body.appendChild(inp);
    scwin.fileInput = inp;
};

scwin.initDropzone = function () {
    var el = scwin.domOf(grp_fDrop);
    if (!el) return;
    el.addEventListener("dragover", function (e) { e.preventDefault(); grp_fDrop.addClass("is-dragover"); });
    el.addEventListener("dragleave", function () { grp_fDrop.removeClass("is-dragover"); });
    el.addEventListener("drop", function (e) {
        e.preventDefault();
        grp_fDrop.removeClass("is-dragover");
        var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
        if (file) scwin.acceptFile(file);
    });
};

scwin.pickImage = function () { if (scwin.fileInput) scwin.fileInput.click(); };
scwin.grp_fDrop_onclick = scwin.pickImage;
scwin.btn_fPick_onclick = scwin.pickImage;

scwin.acceptFile = function (file) {
    if (scwin.IMAGE_TYPES.indexOf(file.type) < 0) {
        scwin.showImageError("Chỉ nhận ảnh JPG, PNG, WEBP hoặc GIF.");
        return;
    }
    if (file.size > scwin.MAX_IMAGE_SIZE) {
        scwin.showImageError("Ảnh nặng " + scwin.fmtSize(file.size) + ", vượt giới hạn 5 MB.");
        return;
    }
    var f = scwin.form;
    scwin.show(tbx_fImgErr, false);
    f.file = file;
    f.removeImage = false;
    scwin.markDirty();
    scwin.revokePreview();
    f.previewUrl = URL.createObjectURL(file);
    scwin.renderPreview(f.previewUrl, file.name + " (" + scwin.fmtSize(file.size) + ")");
};

scwin.showImageError = function (msg) {
    tbx_fImgErr.setValue(msg);
    scwin.show(tbx_fImgErr, true);
};

scwin.renderPreview = function (url, caption) {
    if (url) {
        grp_fDrop.setStyle("background-image", "url(\"" + url + "\")");
        grp_fDrop.addClass("has-image");
        tbx_fImgName.setValue(caption || "Ảnh hiện tại");
        scwin.show(btn_fRemoveImg, true);
    } else {
        grp_fDrop.setStyle("background-image", "none");
        grp_fDrop.removeClass("has-image");
        tbx_fImgName.setValue("Chưa có ảnh");
        scwin.show(btn_fRemoveImg, false);
    }
};

scwin.btn_fRemoveImg_onclick = function () {
    var f = scwin.form;
    f.file = null;
    scwin.revokePreview();
    f.removeImage = !!f.originalImage;
    scwin.markDirty();
    scwin.renderPreview(null);
};

scwin.revokePreview = function () {
    if (scwin.form.previewUrl) {
        try { URL.revokeObjectURL(scwin.form.previewUrl); } catch (e) { }
        scwin.form.previewUrl = null;
    }
};

scwin.onGlobalPaste = function (e) {
    if (!scwin.formOpen || !e.clipboardData) return;
    var items = e.clipboardData.items || [];
    for (var i = 0; i < items.length; i++) {
        if (items[i].kind === "file" && /^image\//.test(items[i].type)) {
            var file = items[i].getAsFile();
            if (file) { e.preventDefault(); scwin.acceptFile(file); }
            return;
        }
    }
};

/* =====================================================================
 * XÓA HỘI TRƯỜNG (soft delete, bắt buộc xác nhận)
 * ===================================================================== */
scwin.openDelete = function () {
    if (!scwin.current) return;
    tbx_delName.setValue(scwin.current.hallName + " (" + scwin.current.hallCode + ")");
    scwin.show(tbx_delErr, false);
    grp_delModal.removeClass("is-blocked");
    try { btn_delConfirm.setDisabled(false); } catch (e) { }
    scwin.deleteOpen = true;
    grp_delMask.addClass("is-open");
    setTimeout(function () { try { btn_delCancel.focus(); } catch (e) { } }, 150);
};

scwin.closeDelete = function () {
    if (scwin.deleteBusy) return;
    scwin.deleteOpen = false;
    grp_delMask.removeClass("is-open");
};
scwin.btn_delCancel_onclick = scwin.closeDelete;

scwin.btn_delConfirm_onclick = function () {
    if (scwin.deleteBusy || !scwin.current) return;
    var h = scwin.current;
    scwin.deleteBusy = true;
    btn_delConfirm.addClass("is-busy");

    scwin.callApi("sbm_hallDelete", { path: "/" + h.hallId + "?confirm=true" }).then(function () {
        scwin.deleteBusy = false;
        scwin.closeDelete();
        scwin.closeDrawer();
        scwin.current = null;
        scwin.toast("Đã xóa hội trường " + h.hallName + ".", "success");
        scwin.search(false);
        scwin.loadStats();
    }).catch(function (err) {
        scwin.deleteBusy = false;
        if (err.code === "HALL_IN_USE") {
            tbx_delErr.setValue((err.message || "Hội trường đang được sự kiện sử dụng.")
                + " Hãy chuyển các sự kiện Nháp/Đang diễn ra sang hội trường khác, hoặc chuyển hội trường này sang Ngưng hoạt động.");
            scwin.show(tbx_delErr, true);
            grp_delModal.addClass("is-blocked");
            try { btn_delConfirm.setDisabled(true); } catch (e) { }
        } else if (err.code === "HALL_NOT_FOUND") {
            scwin.closeDelete();
            scwin.closeDrawer();
            scwin.toast(err.message, "error");
            scwin.search(false);
            scwin.loadStats();
        } else {
            tbx_delErr.setValue(err.message);
            scwin.show(tbx_delErr, true);
        }
    }).then(function () {
        btn_delConfirm.removeClass("is-busy");
    });
};

/* =====================================================================
 * PHÍM TẮT & THÔNG BÁO
 *   Esc: đóng lớp trên cùng | Ctrl/Cmd+Enter: lưu form | "/": tìm kiếm
 * ===================================================================== */
scwin.onGlobalKeydown = function (e) {
    var key = e.key;
    if (key === "Escape") {
        if (scwin.deleteOpen) scwin.closeDelete();
        else if (scwin.formOpen) scwin.closeForm(false);
        else if (scwin.drawerOpen) scwin.closeDrawer();
        return;
    }
    if (scwin.formOpen && key === "Enter" && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
        scwin.btn_fSave_onclick();
        return;
    }
    var tag = (e.target && e.target.tagName ? e.target.tagName : "").toLowerCase();
    if (key === "/" && tag !== "input" && tag !== "textarea" && !scwin.formOpen && !scwin.deleteOpen) {
        e.preventDefault();
        try { ibx_keyword.focus(); } catch (err) { }
    }
};

scwin.toast = function (msg, type) {
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["hm-toast--success", "hm-toast--error", "hm-toast--warning", "hm-toast--info"].forEach(function (c) { tbx_toast.removeClass(c); });
    tbx_toast.addClass("hm-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, type === "error" ? 6000 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
